INSERT INTO public.token_datasets (slug, name, description, industry, modality, total_tokens, price_per_1k_tokens, package_options, quality_score, license, tags, provider_name, sample_url) VALUES
('industrial-defect-vision-cn', '中国制造业缺陷检测图像集', '覆盖 12 类工业产品（汽车零件、PCB、铸件、纺织品等）的高分辨率缺陷图像，含像素级标注与缺陷类别标签，适用于视觉检测大模型预训练与微调。', '工业制造', 'image', 8500000000, 1.20, '[{"tokens":1000000,"price":1100},{"tokens":10000000,"price":9800},{"tokens":100000000,"price":86000}]'::jsonb, 9.2, 'CC-BY-NC 4.0', ARRAY['工业视觉','缺陷检测','多模态'], '智造数据科技', 'https://example.com/sample/industrial.json'),
('clinical-emr-zh-corpus', '中文临床电子病历语料', '脱敏后中文三甲医院病历语料 12 亿词元，覆盖内/外/妇/儿/急诊 30 个科室，含 ICD-10 编码与结构化字段，适用于医疗大模型预训练与下游 NER/关系抽取。', '医疗健康', 'text', 1200000000, 2.50, '[{"tokens":500000,"price":1200},{"tokens":5000000,"price":11500},{"tokens":50000000,"price":105000}]'::jsonb, 9.5, '商业授权', ARRAY['医疗NLP','临床文本','脱敏'], '康健数据', 'https://example.com/sample/emr.json'),
('finrisk-knowledge-graph', '金融风控知识图谱', '覆盖 80 万家中国上市/非上市企业的股权穿透、关联交易、舆情风险知识图谱，节点 800 万+，边 4500 万+，按 token 化三元组计费。', '金融服务', 'kg', 4500000000, 3.00, '[{"tokens":1000000,"price":2900},{"tokens":10000000,"price":27000},{"tokens":100000000,"price":240000}]'::jsonb, 9.0, '商业授权', ARRAY['知识图谱','风控','企业图谱'], '风控图谱实验室', 'https://example.com/sample/kg.json'),
('hk-traffic-multimodal', '香港跨境交通多模态数据集', '深港、港珠澳大桥跨境通关车辆视频、车牌识别、通关时长、天气数据多模态对齐集合，适用于交通智能体训练。', '交通运输', 'video', 2000000000, 2.00, '[{"tokens":500000,"price":950},{"tokens":5000000,"price":9000},{"tokens":50000000,"price":82000}]'::jsonb, 8.7, 'CC-BY 4.0', ARRAY['跨境交通','多模态','香港'], 'HKBDE 交通数据中心', 'https://example.com/sample/traffic.json'),
('cultural-tourism-audio-cn', '文化旅游多语种音频导览集', '50 个 5A 景区中、英、粤、日、韩 5 语种专业导览音频与逐字稿对齐数据，3.2 亿音频词元，适用于文旅大模型与语音克隆。', '文化旅游', 'audio', 320000000, 1.80, '[{"tokens":500000,"price":850},{"tokens":5000000,"price":8000},{"tokens":50000000,"price":72000}]'::jsonb, 8.9, 'CC-BY-NC 4.0', ARRAY['文旅','多语种','语音'], '文旅数据联盟', 'https://example.com/sample/tour.json'),
('city-iot-timeseries-gba', '大湾区城市 IoT 时序集', '大湾区 9+2 城市路网、电网、水务、垃圾分类等 18 类 IoT 传感器 5 年时序数据，按时间步词元化，适用于城市运营智能体。', '城市治理', 'text', 6000000000, 1.50, '[{"tokens":1000000,"price":1450},{"tokens":10000000,"price":13500},{"tokens":100000000,"price":120000}]'::jsonb, 8.8, '商业授权', ARRAY['智慧城市','IoT','时序'], '湾区智慧城市平台', 'https://example.com/sample/iot.json'),
('embodied-warehouse-rl', '仓储具身智能交互数据集', '基于真机 + 仿真混合采集的仓储拣选机器人物理交互轨迹数据，含 RGBD、力反馈、抓取成功标签，可直接用于具身大模型 RL 训练。', '工业制造', 'embodied', 850000000, 4.50, '[{"tokens":500000,"price":2200},{"tokens":5000000,"price":21000},{"tokens":50000000,"price":195000}]'::jsonb, 9.3, '商业授权', ARRAY['具身智能','机器人','强化学习'], '具身智能研究院', 'https://example.com/sample/embodied.json');